import React, { useEffect } from "react";
import axios from "axios";

const API_KEY = "dict.1.1.20261026T153249Z.2084c047cc3fe9cd.969421bfa31d2e4e1dada50a256e240334d19899";

const doTranslation = async (input, cancelToken) => {
  const response = await axios.get(
    "https://translate.yandex.net/api/v1.5/tr.json/translate",
    {
      params: {
        key: API_KEY,
        text: input,
        lang: "ru-en"
      },
      cancelToken: cancelToken.token
    }
  );

  if (response.data.code !== 200) {
    throw new Error("API вернул ошибку");
  }

  return response.data.text[0];
};

export default function Translate({
  text,
  translated,
  onTranslated
}) {
  useEffect(() => {
    if (!text.trim()) {
      onTranslated("");
      return;
    }

    const cancelToken = axios.CancelToken.source();

    const timer = setTimeout(() => {
      doTranslation(text.trim(), cancelToken)
      .then(onTranslated)
      .catch((error) => {
        if (!axios.isCancel(error)) {
          console.error("Ошибка перевода:", error);
          onTranslated("Не удалось перевести");
        }
      });
    }, 400);

    return () => {
      clearTimeout(timer);
      cancelToken.cancel();
    };
  }, [text, onTranslated]);

  return <h1 className="title">{translated}</h1>;
}
